/// form-actions-bar: Unsaved changes
private struct FormActionsBarExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var name = "Northwind Ltd"
    @State private var savedName = "Northwind"
    @State private var email = "team@example.com"
    @State private var isSaving = false
    @State private var isConfirmingDiscard = false

    private var isDirty: Bool { name != savedName }

    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            VStack(alignment: .leading, spacing: theme.spacing.space3) {
                MonarchTextField("Workspace name", text: $name)
                MonarchTextField("Contact email", text: $email)
            }
            .padding(theme.spacing.space4)
            Divider()
            VStack(alignment: .leading, spacing: theme.spacing.space2) {
                if isDirty {
                    Text("You have unsaved changes")
                        .monarchTextStyle(.body)
                        .foregroundStyle(theme.colors.textMuted)
                }
                HStack(spacing: theme.spacing.space2) {
                    Spacer()
                    MonarchButton("Discard", variant: .ghost) { isConfirmingDiscard = true }
                        .disabled(!isDirty || isSaving)
                    if isSaving {
                        ProgressView().accessibilityLabel("Saving")
                    } else {
                        MonarchButton("Save changes", variant: .primary) { savedName = name }
                            .disabled(!isDirty)
                    }
                }
            }
            .padding(theme.spacing.space4)
        }
        .confirmationDialog("Discard unsaved changes?", isPresented: $isConfirmingDiscard, titleVisibility: .visible) {
            Button("Discard changes", role: .destructive) { name = savedName }
            Button("Keep editing", role: .cancel) {}
        } message: {
            Text("Your changes will be lost. This cannot be undone.")
        }
    }
}

