/// slider: Stream and commit
private struct SliderExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var volume = 60.0
    @State private var saved = 60.0

    /// SwiftUI's Slider cannot be restyled, so the track and its ring thumb are drawn here from the theme.
    private struct RingSlider: View {
        @Binding var value: Double
        let range: ClosedRange<Double>
        let label: String
        let onEditingChanged: (Bool) -> Void

        @Environment(\.monarchTheme) private var theme
        @State private var isDragging = false

        var body: some View {
            GeometryReader { proxy in
                let thumb = theme.spacing.space5
                let span = max(proxy.size.width - thumb, 1)
                let fraction = (value - range.lowerBound) / (range.upperBound - range.lowerBound)
                ZStack(alignment: .leading) {
                    Capsule().fill(theme.colors.bgEmphasis).frame(height: theme.spacing.space1_5)
                    Capsule().fill(theme.colors.accentSolid)
                        .frame(width: thumb / 2 + span * fraction, height: theme.spacing.space1_5)
                    Circle().fill(theme.colors.bgSurface)
                        .overlay(Circle().strokeBorder(theme.colors.accentSolid, lineWidth: theme.spacing.space0_5))
                        .frame(width: thumb, height: thumb)
                        .offset(x: span * fraction)
                }
                .frame(maxHeight: .infinity)
                .contentShape(Rectangle())
                .gesture(
                    DragGesture(minimumDistance: 0)
                        .onChanged { drag in
                            if !isDragging {
                                isDragging = true
                                onEditingChanged(true)
                            }
                            let share = min(max((drag.location.x - thumb / 2) / span, 0), 1)
                            value = (range.lowerBound + share * (range.upperBound - range.lowerBound)).rounded()
                        }
                        .onEnded { _ in
                            isDragging = false
                            onEditingChanged(false)
                        }
                )
            }
            .frame(height: 44)
            .accessibilityElement()
            .accessibilityLabel(label)
            .accessibilityValue(Text(Int(value), format: .number))
            .accessibilityAdjustableAction { direction in
                switch direction {
                case .increment: value = min(value + 1, range.upperBound)
                case .decrement: value = max(value - 1, range.lowerBound)
                @unknown default: break
                }
                onEditingChanged(false)
            }
        }
    }

    var body: some View {
        VStack(alignment: .leading, spacing: theme.spacing.space1) {
            Text("Notification volume").monarchTextStyle(.label)
            HStack {
                RingSlider(
                    value: $volume,
                    range: 0.0...100.0,
                    label: "Notification volume",
                    onEditingChanged: { editing in
                        if !editing { saved = volume }
                    }
                )
                Text("\(Int(volume))").monarchTextStyle(.caption)
            }
            Text("Saved at \(Int(saved)).").monarchTextStyle(.caption)
        }
    }
}

