        MonarchTemplatePickerItem(id: "gallery", name: "Gallery", description: "Cards in a grid.", category: "pages", image: Self.thumbnail("gallery", dark: scheme == .dark)),
        MonarchTemplatePickerItem(id: "split", name: "Split", description: "Image beside text.", category: "pages", image: Self.thumbnail("split", dark: scheme == .dark)),
        MonarchTemplatePickerItem(id: "article", name: "Article", description: "One readable column.", category: "docs", image: Self.thumbnail("article", dark: scheme == .dark), keywords: ["blog", "post"]),
        MonarchTemplatePickerItem(id: "intake", name: "Intake form", description: "Collect details before a call.", category: "forms", image: Self.thumbnail("intake", dark: scheme == .dark)),
    ] }

    /// A small picture of each layout, as the web draws: a page with a red heading bar and grey lines.
    private static func thumbnail(_ id: String, dark: Bool) -> Image {
        let width = 320, height = 200
        guard let context = CGContext(
            data: nil, width: width, height: height, bitsPerComponent: 8, bytesPerRow: 0,
            space: CGColorSpaceCreateDeviceRGB(), bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
        ) else { return Image(systemName: "doc") }
        // Core Graphics counts up from the bottom: flip it so the picture is drawn from the top left.
        context.translateBy(x: 0, y: CGFloat(height))
        context.scaleBy(x: 1, y: -1)
        let red = CGColor(red: 0.86, green: 0.15, blue: 0.22, alpha: 1)
        let grey = dark ? CGColor(red: 0.27, green: 0.27, blue: 0.31, alpha: 1) : CGColor(red: 0.8, green: 0.8, blue: 0.82, alpha: 1)
        let pink = dark ? CGColor(red: 0.24, green: 0.1, blue: 0.12, alpha: 1) : CGColor(red: 0.99, green: 0.9, blue: 0.91, alpha: 1)
        func bar(_ x: CGFloat, _ y: CGFloat, _ length: CGFloat, _ color: CGColor) {
            context.setFillColor(color)
            context.addPath(CGPath(roundedRect: CGRect(x: x, y: y, width: length, height: 8), cornerWidth: 3, cornerHeight: 3, transform: nil))
            context.fillPath()
        }
        func box(_ x: CGFloat, _ y: CGFloat, _ boxWidth: CGFloat, _ boxHeight: CGFloat, fill: CGColor? = nil) {
            context.addPath(CGPath(roundedRect: CGRect(x: x, y: y, width: boxWidth, height: boxHeight), cornerWidth: 6, cornerHeight: 6, transform: nil))
            if let fill {
                context.setFillColor(fill)
                context.fillPath()
            } else {
                context.setStrokeColor(grey)
                context.setLineWidth(2)
                context.strokePath()
            }
        }
        context.setFillColor(dark ? CGColor(red: 0.09, green: 0.09, blue: 0.12, alpha: 1) : CGColor(red: 1, green: 1, blue: 1, alpha: 1))
        context.fill(CGRect(x: 0, y: 0, width: width, height: height))
        switch id {
        case "classic":
            bar(24, 28, 80, red)
            for row in 0..<3 { bar(24, CGFloat(52 + row * 18), 90, grey) }
            box(136, 24, 160, 32)
            for row in 0..<2 { bar(136, CGFloat(70 + row * 18), 160, grey) }
        case "banner":
            box(24, 20, 272, 52, fill: pink)
            bar(24, 88, 120, red)
            for row in 0..<3 { bar(24, CGFloat(112 + row * 18), 272, grey) }
        case "gallery":
            for row in 0..<2 {
                for column in 0..<3 { box(CGFloat(24 + column * 92), CGFloat(24 + row * 76), 80, 64) }
            }
        case "split":
            box(24, 28, 110, 140, fill: pink)
            bar(158, 40, 100, red)
            for row in 0..<3 { bar(158, CGFloat(66 + row * 18), 138, grey) }
        case "article":
            bar(24, 28, 110, red)
            for row in 0..<6 { bar(24, CGFloat(54 + row * 18), 272, grey) }
        default:
            bar(24, 24, 110, red)
            for row in 0..<3 { box(24, CGFloat(48 + row * 44), 272, 32) }
        }
        guard let picture = context.makeImage() else { return Image(systemName: "doc") }
        return Image(decorative: picture, scale: 1)
    }

    var body: some View {
        VStack(alignment: .leading, spacing: theme.spacing.space4) {
            HStack(spacing: theme.spacing.space2) {
                MonarchIcon(systemName: "magnifyingglass", size: .sm)
                    .foregroundStyle(theme.colors.textMuted)
                    .accessibilityHidden(true)
                TextField("Search templates", text: $query)
                    .monarchTextStyle(.body)
            }
            .padding(.horizontal, theme.spacing.space3)
            .frame(minHeight: MonarchAccessibility.minimumHitTarget)
            .overlay(
                RoundedRectangle(cornerRadius: theme.radius.md)
                    .strokeBorder(theme.colors.borderDefault, lineWidth: 1)
            )
            MonarchTemplatePicker(
                "Page template",
                selection: $selection,
                templates: templates,
                categories: [
                    MonarchTemplatePickerCategory(id: "pages", label: "Pages"),
                    MonarchTemplatePickerCategory(id: "docs", label: "Articles"),
                    MonarchTemplatePickerCategory(id: "forms", label: "Forms"),
                ],
                query: query,
                blank: .blank(description: "Start from an empty page.")
            )
            if let chosen = templates.first(where: { $0.id == selection }) {
                VStack(alignment: .leading, spacing: theme.spacing.space2) {
                    Self.thumbnail(chosen.id, dark: scheme == .dark)
                        .resizable()
                        .aspectRatio(contentMode: .fit)
                        .frame(maxWidth: .infinity)
                        .background(theme.colors.bgSubtle)
                        .accessibilityHidden(true)
                    Text(chosen.name)
                        .monarchTextStyle(.bodyStrong)
                        .foregroundStyle(theme.colors.textDefault)
                    if let description = chosen.description {
                        Text(description)
                            .monarchTextStyle(.body)
                            .foregroundStyle(theme.colors.textMuted)
                    }
                }
                .padding(theme.spacing.space3)
                .overlay(
                    RoundedRectangle(cornerRadius: theme.radius.lg)
                        .strokeBorder(theme.colors.borderSubtle, lineWidth: 1)
                )
                .accessibilityElement(children: .contain)
                .accessibilityLabel("Preview")
            }
        }
    }
}

